Java三种方法将List转换为Map的实例1.for循环
&lt;pre class=&quot;brush:java;&quot;&gt;import com.google.common.base.Function;import com.google.common.collect.Maps;import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map;public class ListToMap &#123;  public static void main(String[] args) &#123;    List&lt;User&gt; userList = new ArrayList&lt;&gt;();    User user1 = new User();    user1.setId(1L);    user1.setAge(&quot;12&quot;);    User user2 = new User();    user2.setId(2L);    user2.setAge(&quot;13&quot;);    userList.add(user1);    userList.add(user2);    Map&lt;Long, User&gt; maps = new HashMap&lt;&gt;();    for (User user : userList) &#123;      maps.put(user.getId(), user);    &#125;    System.out.println(maps);  &#125;  public static class User &#123;    private Long id;    private String age;    public Long getId() &#123;      return id;    &#125;    public void setId(Long id) &#123;      this.id = id;    &#125;    public String getAge() &#123;      return age;    &#125;    public void setAge(String age) &#123;      this.age = age;    &#125;    @Override    public String toString() &#123;      return &quot;User&#123;&quot; +          &quot;id=&quot; + id +          &quot;, age=&#x27;&quot; + age + &#x27;\&#x27;&#x27; +          &#x27;&#125;&#x27;;    &#125;  &#125;&#125;&lt;/pre&gt;

2.使用guava
