package com.demo.config;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.context.annotation.Profile;import io.swagger.annotations.Api;import springfox.documentation.builders.ApiInfoBuilder;import springfox.documentation.builders.PathSelectors;import springfox.documentation.builders.RequestHandlerSelectors;import springfox.documentation.service.ApiInfo;import springfox.documentation.service.Contact;import springfox.documentation.spi.DocumentationType;import springfox.documentation.spring.web.plugins.Docket;import springfox.documentation.swagger2.annotations.EnableSwagger2;/*** Swagger2配置* http://localhost:18005/swagger-ui.html* http://localhost:18005/doc.html*/@Configuration@EnableSwagger2@Profile(&#123;&quot;dev&quot;, &quot;pre&quot;&#125;)class SwaggerConfig &#123;/*** swagger2的配置文件，这里可以配置swagger2的一些基本的内容，比如扫描的包等等*/@Beanpublic Docket createRestApi() &#123;return new Docket(DocumentationType.SWAGGER_2).apiInfo(apiInfo()).select().apis(RequestHandlerSelectors.withClassAnnotation(Api.class))//为当前包路径//.apis(RequestHandlerSelectors.basePackage(&quot;com.br.demo.controller&quot;)).paths(PathSelectors.any()).build();&#125;/*** 构建 api文档的详细信息函数*/private ApiInfo apiInfo() &#123;ApiInfo apiInfo = new ApiInfoBuilder()//页面标题.title(&quot;账务系统接口API文档&quot;)//创建人.contact(new Contact(&quot;xx&quot;, &quot;http://xx.100credit.cn&quot;, &quot;xx@100credit.com&quot;))//版本号.version(&quot;1.0&quot;)//描述.description(&quot;账务系统接口大全&quot;).build();return apiInfo;&#125;&#125;

