代码取自：JAVA根据URL网址获取输入流
/** * 根据地址获得数据的输入流 * @param strUrl 网络连接地址 * @return url的输入流 */    public static InputStream getInputStreamByUrl(String strUrl)&#123;        HttpURLConnection conn = null;        try &#123;            URL url = new URL(strUrl);            conn = (HttpURLConnection)url.openConnection();            conn.setRequestMethod(&quot;GET&quot;);            conn.setConnectTimeout(20 * 1000);            final ByteArrayOutputStream output = new ByteArrayOutputStream();            IOUtils.copy(conn.getInputStream(),output);            return  new ByteArrayInputStream(output.toByteArray());        &#125; catch (Exception e) &#123;            logger.error(e+&quot;&quot;);        &#125;finally &#123;            try&#123;                if (conn != null) &#123;                    conn.disconnect();                &#125;            &#125;catch (Exception e)&#123;                logger.error(e+&quot;&quot;);            &#125;        &#125;        return null;    &#125;

如若想下载文件，则可以在上面方法基础上，进一步封装即可：\
public ResponseEntity&lt;byte[]&gt; downloadFileByUrl(String downUrl, String fileName, String contentType, String contentDisposition) throws IOException &#123;        InputStream inputStream = getInputStreamByUrl(downUrl);        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();        IOUtils.copy(inputStream, byteArrayOutputStream);        inputStream.close();        HttpHeaders headers = new HttpHeaders();        //设置下载协议头。下面fileName的两次转换主要是为了保证中文文件名        fileName = new String(fileName.getBytes(StandardCharsets.UTF_8), StandardCharsets.ISO_8859_1);        headers.set(HttpHeaders.CONTENT_DISPOSITION, contentDisposition + &quot;;filename=&quot; + new String(fileName.getBytes(), &quot;utf-8&quot;));        headers.set(HttpHeaders.CONTENT_TYPE, contentType);        ResponseEntity&lt;byte[]&gt; responseEntity = new ResponseEntity&lt;byte[]&gt;(byteArrayOutputStream.toByteArray(), headers, HttpStatus.OK);        byteArrayOutputStream.close();        return responseEntity;    &#125;

其中Content-Type可以用MediaType中的常量，自行控制；Content-Disposition则看需求，如果需要直接打开文件，则传”inline”，若是想下载则传”attachment”。

